import 'dart:convert';
import 'dart:io';

/// One benchmark transcript with its reference material (plan §7).
///
/// Reference summaries must be human-written, never generated by Gemma.
class BenchmarkFixture {
  const BenchmarkFixture({
    required this.id,
    required this.title,
    required this.language,
    required this.durationMinutes,
    required this.transcript,
    required this.referenceSummary,
    required this.importantFacts,
    required this.importantEntities,
    required this.importantNumbers,
    this.category = '',
    this.size = '',
  });

  factory BenchmarkFixture.fromJson(Map<String, dynamic> json) => BenchmarkFixture(
    id: json['id'] as String,
    title: json['title'] as String,
    language: json['language'] as String,
    durationMinutes: (json['duration_minutes'] as num).toInt(),
    transcript: json['transcript'] as String,
    referenceSummary: json['reference_summary'] as String,
    importantFacts: List<String>.from(json['important_facts'] as List),
    importantEntities: List<String>.from(json['important_entities'] as List),
    importantNumbers: List<String>.from(json['important_numbers'] as List),
    category: json['category'] as String? ?? '',
    size: json['size'] as String? ?? '',
  );

  final String id;
  final String title;
  final String language;
  final int durationMinutes;
  final String transcript;
  final String referenceSummary;
  final List<String> importantFacts;
  final List<String> importantEntities;
  final List<String> importantNumbers;

  /// Free-text tags, e.g. `msa`, `levantine`, `technical`.
  final String category;

  /// `short`, `medium` or `long`.
  final String size;

  static Future<List<BenchmarkFixture>> loadDirectory(Directory directory) async {
    final files =
        directory.listSync().whereType<File>().where((f) => f.path.endsWith('.json')).toList()
          ..sort((a, b) => a.path.compareTo(b.path));
    return [
      for (final f in files)
        BenchmarkFixture.fromJson(jsonDecode(await f.readAsString()) as Map<String, dynamic>),
    ];
  }
}
